+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'file_metadata') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  const { path: relPath } = args;
+  if (typeof relPath !== 'string' || relPath.length === 0) {
+    throw new Error('Parameter "path" is required and must be a non-empty string.');
+  }
+
+  // Resolve and ensure the resulting path stays within the data directory.
+  const fullPath = path.resolve(DATA_DIR, relPath);
+  if (fullPath !== DATA_DIR && !fullPath.startsWith(DATA_DIR + path.sep)) {
+    throw new Error('Path traversal outside the data directory is not allowed.');
+  }
+
+  let stat;
+  try {
+    stat = await fs.stat(fullPath);
+  } catch (err) {
+    throw new Error(`File not found: ${relPath}`);
+  }
+  if (!stat.isFile()) {
+    throw new Error(`Not a file: ${relPath}`);
+  }
+
+  const ext = path.extname(relPath).toLowerCase();
+  const text = `path: ${relPath}\nsize: ${stat.size} bytes\nextension: ${ext}`;
+
+  return {
+    content: [{ type: 'text', text }]
+  };
+}
